'use strict';

// MODULES //

var stride2offset = require( '@stdlib/strided/base/stride2offset' );
var ndarray = require( './ndarray.js' );


// MAIN //

/**
* Computes the cross product of two input strided arrays and assigns the results to an output strided array.
*
* @param {NumericArray} x - first input array
* @param {integer} strideX - stride length for `x`
* @param {NumericArray} y - second input array
* @param {integer} strideY - stride length for `y`
* @param {NumericArray} z - output array
* @param {integer} strideZ - stride length for `z`
* @returns {NumericArray} output array
*
* @example
* var x = [ 1.0, 2.0, 3.0 ];
* var y = [ 4.0, 5.0, 6.0 ];
* var z = [ 0.0, 0.0, 0.0 ];
*
* gcross( x, 1, y, 1, z, 1 );
* // z => [ -3.0, 6.0, -3.0 ]
*/
function gcross( x, strideX, y, strideY, z, strideZ ) {
	var ox = stride2offset( 3, strideX );
	var oy = stride2offset( 3, strideY );
	var oz = stride2offset( 3, strideZ );
	return ndarray( x, strideX, ox, y, strideY, oy, z, strideZ, oz );
}


// EXPORTS //

module.exports = gcross;
